mapper.select:
SELECT id, trip_plan_id, user_id, role, status, created_at, updated_at
  FROM trip_members
 WHERE trip_plan_id = #{planId}
   AND user_id = #{userId}

mapper.update:
UPDATE trip_members
   SET status = 'ACCEPTED'
 WHERE trip_plan_id = #{planId}
   AND user_id = #{userId}
   AND status = 'PENDING'

mapper.delete:
DELETE FROM trip_members
 WHERE trip_plan_id = #{planId}
   AND user_id = #{userId}
   AND status = 'PENDING'

mapper.update:
UPDATE trip_members
   SET role = #{role}
 WHERE trip_plan_id = #{planId}
   AND user_id = #{userId}

mapper.delete:
DELETE FROM trip_members
 WHERE trip_plan_id = #{planId}
   AND user_id = #{userId}
